import Foundation
import Testing
@testable import XTouchCompactCore

/// Every row is generated by the real host state machine; time is a deterministic input label.
private struct BehaviorTrace {
    var session = try! CompactSession(map: FactoryStandardMap(), lightProtocol: .manual)
    var mock = try! MockXTouchCompact(map: FactoryStandardMap(), lightProtocol: .manual)
    var rows: [[String: Any]] = []

    mutating func step(_ operation: String, raw: [MIDIMessage] = [], fails: Bool = false,
                       run: (inout CompactSession) throws -> [MIDIMessage]) throws
    {
        let before = session.parameters.values
        let pendingBefore = (1 ... 9).filter { session.state.isMotorPending($0) }
        let output = try run(&session)
        let permitted = session.filterFeedbackForDelivery(output)
        if fails {
            session.invalidateTransportFeedback()
        } else {
            mock.receive(permitted)
        }
        var changes: [String: Double] = [:]
        for (key, value) in session.parameters.values where before[key] != value {
            changes[key] = value
        }
        let pending = (1 ... 9).filter { session.state.isMotorPending($0) }
        let cancelled = session.state.layerMismatch ? pendingBefore.filter { !pending.contains($0) } : []
        rows.append([
            "input": ["operation": operation, "raw_messages": raw.map(\.midi1Bytes),
                      "hardware_context": raw.first.flatMap { session.state.map.decode($0)?.layer.rawValue } as Any? ?? NSNull(),
                      "injected_time": Double(rows.count) / 10],
            "result": ["accepted": true, "rejection_reason": NSNull(), "parameter_changes": changes, "action_count": 0],
            "output": ["sent": fails ? [] : permitted.map(\.midi1Bytes),
                       "failed": fails ? permitted.map(\.midi1Bytes) : [],
                       "deferred": pending.map { ["control": "fader.\($0)", "reason": "touch"] },
                       "suppressed": output.filter { !permitted.contains($0) }.map { ["message": $0.midi1Bytes, "reason": "delivery_safety_gate"] },
                       "cancelled": cancelled.map { ["control": "fader.\($0)", "reason": "layer_mismatch"] }],
            "observation": ["host_layer": session.state.layer.rawValue,
                            "observed_layer": session.state.observedLayer?.rawValue as Any? ?? NSNull(),
                            "layer_mismatch": session.state.layerMismatch,
                            "fader_1_observed": session.state.observedFader(1).map { Int($0) } as Any? ?? NSNull(),
                            "fader_1_observation_current": NSNull(), "last_sent_motor": NSNull(),
                            "touched": (1 ... 9).filter { session.state.isTouched($0) }, "pending_motor": pending],
        ])
    }

    mutating func input(_ message: MIDIMessage) throws {
        try step("receive", raw: [message]) { try $0.receive([message]).feedback }
    }
}

/// Declarations belong to this device's test harness, never to a shared decoder.
private enum TraceDeclaration {
    static func elementRole(_ control: CompactControl) -> (String, String) {
        switch control {
        case let .fader(i): ("fader.\(i)", "position")
        case let .faderTouch(i): ("fader.\(i)", "touch")
        case let .encoder(i): ("encoder.\(i)", "rotation")
        case let .encoderPush(i): ("encoder.\(i)", "press")
        case let .button(i): ("button.\(i)", "press")
        case .expression: ("pedal.expression", "position")
        case .footswitch: ("pedal.switch", "press")
        }
    }

    static func decodeBytes(_ value: Any) throws -> MIDIMessage {
        let bytes = try #require(value as? [UInt8])
        #expect(bytes.count == 2 || bytes.count == 3)
        let word = UInt32(0x2000_0000) | UInt32(bytes[0]) << 16 | UInt32(bytes[1]) << 8 | UInt32(bytes.count == 3 ? bytes[2] : 0)
        return try #require(MIDI1UMPCodec.decode(word))
    }

    static func effect(_ message: MIDIMessage, map: FactoryStandardMap) throws -> [String: Any] {
        if case .programChange = message {
            return ["category": "management", "target": "device.layer", "affected": (1 ... 9).map { "fader.\($0)" }, "side_effects": ["motion"]]
        }
        let address: MIDIAddress
        switch message {
        case let .controlChange(c, n, _): address = MIDIAddress(messageType: .controlChange, channel: c, number: n)
        case let .noteOn(c, n, _), let .noteOff(c, n, _): address = MIDIAddress(messageType: .note, channel: c, number: n)
        default: throw CompactError.invalidMIDIValue(255)
        }
        let controls = (1 ... 9).map(CompactControl.fader) + (1 ... 16).map(CompactControl.encoder) + (1 ... 39).map(CompactControl.button)
        for control in controls where map.feedbackAddress(for: control) == address {
            let element = elementRole(control).0
            switch control {
            case .fader: return ["category": "motion", "target": element + ".motor", "affected": [element]]
            case .encoder: return ["category": "display", "target": element + ".ring", "affected": [element]]
            case .button: return ["category": "display", "target": element + ".light", "affected": [element]]
            default: break
            }
        }
        for i in 1 ... 16 where map.encoderRingStyleAddress(encoder: i) == address {
            return ["category": "display", "target": "encoder.\(i).ring.style", "affected": ["encoder.\(i)"]]
        }
        throw CompactError.invalidMIDIValue(address.number)
    }

    static func rows(_ original: [[String: Any]]) throws -> [[String: Any]] {
        let map = try FactoryStandardMap()
        var positionState = "unknown"
        var hasTouchEvidence = false
        return try original.map { row in
            var row = row
            var input = try #require(row["input"] as? [String: Any])
            let bytes = try #require(input["raw_messages"] as? [[UInt8]])
            let event = try bytes.first.flatMap { try map.decode(decodeBytes($0)) }
            input["element"] = event.map { elementRole($0.control).0 } as Any? ?? NSNull()
            input["role"] = event.map { elementRole($0.control).1 } as Any? ?? NSNull()
            input["context"] = ["kind": "layer", "value": event?.layer.rawValue as Any? ?? NSNull()]
            if let event {
                if event.control == .fader(1) {
                    positionState = "observed"
                }
                if case .faderTouch = event.control {
                    hasTouchEvidence = true
                }
            }
            var output = try #require(row["output"] as? [String: Any])
            var effects: [[String: Any]] = []
            var sentObservations: [[String: Any]] = []
            for key in output.keys.sorted() {
                let values = try #require(output[key] as? [Any])
                for (index, value) in values.enumerated() {
                    let path = "/output/\(key)/\(index)"
                    var declared: [String: Any]
                    if let record = value as? [String: Any], let control = record["control"] as? String {
                        declared = ["category": "motion", "target": control + ".motor", "affected": [control]]
                    } else if let record = value as? [String: Any], record["affected_controls"] != nil {
                        // This is the harness's refused request_layer_b operation.
                        declared = try effect(map.selectLayer(.b), map: map)
                    } else {
                        let raw = (value as? [String: Any])?["message"] ?? value
                        declared = try effect(decodeBytes(raw), map: map)
                    }
                    declared["source_field"] = path
                    effects.append(declared)
                    if key == "sent" || key == "failed",
                       declared["target"] as? String == "fader.1.motor" || declared["target"] as? String == "device.layer"
                    {
                        // These actual state operations invalidate position freshness even if delivery later fails.
                        positionState = "stale"
                    }
                    if key == "sent" {
                        sentObservations.append(["source_field": path, "state": "sent_only", "target": declared["target"]!, "value": value])
                    }
                }
            }
            output["declarations"] = effects
            var observation = try #require(row["observation"] as? [String: Any])
            var observations: [[String: Any]] = observation.keys.sorted().map { key in
                let state: Any = switch key {
                case "observed_layer": observation[key] is NSNull ? "unknown" : "observed"
                case "fader_1_observed": observation[key] is NSNull ? "unknown" : positionState
                case "touched": hasTouchEvidence ? "observed" : "unknown"
                default: NSNull() // Host intent or a private/unavailable state, not physical observation.
                }
                return ["source_field": "/observation/\(key)", "state": state]
            }
            observations += sentObservations
            observation["declarations"] = observations
            row["input"] = input; row["output"] = output; row["observation"] = observation
            return row
        }
    }
}

@Test func neutralTraceDeclarationsKeepPhysicalIdentityAndDeclareLayerMotion() throws {
    let map = try FactoryStandardMap()
    for layer in CompactLayer.allCases {
        let position = try #require(map.inputAddress(for: .fader(1), layer: layer))
        let touch = try #require(map.inputAddress(for: .faderTouch(1), layer: layer))
        for (address, role) in [(position, "position"), (touch, "touch")] {
            let event = try #require(map.decode(.controlChange(channel: address.channel, number: address.number, value: 127)))
            #expect(TraceDeclaration.elementRole(event.control).0 == "fader.1")
            #expect(TraceDeclaration.elementRole(event.control).1 == role)
        }
        let effect = try TraceDeclaration.effect(map.selectLayer(layer), map: map)
        #expect(effect["category"] as? String == "management")
        #expect(effect["side_effects"] as? [String] == ["motion"])
        #expect(effect["affected"] as? [String] == (1 ... 9).map { "fader.\($0)" })
    }
}

private enum TraceJSONContent: Decodable, Equatable {
    case object([String: TraceJSONContent]), array([TraceJSONContent])
    case number(Double), string(String), bool(Bool), null

    init(from decoder: any Decoder) throws {
        let value = try decoder.singleValueContainer()
        if value.decodeNil() {
            self = .null
        } else if let bool = try? value.decode(Bool.self) {
            self = .bool(bool)
        } else if let string = try? value.decode(String.self) {
            self = .string(string)
        } else if let array = try? value.decode([TraceJSONContent].self) {
            self = .array(array)
        } else if let object = try? value.decode([String: TraceJSONContent].self) {
            self = .object(object)
        } else {
            self = try .number(value.decode(Double.self))
        }
    }
}

@Test func traceJSONContentPreservesDifferencesWithoutDependingOnNumberSpelling() throws {
    func content(_ json: String) throws -> TraceJSONContent {
        try JSONDecoder().decode(TraceJSONContent.self, from: Data(json.utf8))
    }
    let baseline = try content(#"{"time":0.10000000000000001,"values":[1,true,null,"motor"]}"#)
    #expect(try baseline == content(#"{ "values" : [1.0, true, null, "motor"], "time" : 0.1 }"#))
    for changed in [
        #"{"time":0.2,"values":[1,true,null,"motor"]}"#,
        #"{"time":0.1,"values":[2,true,null,"motor"]}"#,
        #"{"time":0.1,"values":[true,1,null,"motor"]}"#,
        #"{"time":0.1,"values":[1,1,null,"motor"]}"#,
        #"{"time":0.1,"values":[1,true,false,"motor"]}"#,
        #"{"time":0.1,"values":[1,true,null,"light"]}"#,
        #"{"time":0.1,"values":[1,true,null]}"#,
        #"{"values":[1,true,null,"motor"]}"#,
        #"{"time":0.1,"values":[1,true,null,"motor"],"extra":null}"#,
    ] {
        #expect(try baseline != content(changed))
    }
}

@Test func mockBehaviorTracesMatchCheckedInBytes() throws {
    let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("Fixtures/BehaviorTraces")
    var traces: [String: BehaviorTrace] = [:]
    let touch = MIDIMessage.controlChange(channel: 0, number: 101, value: 127)
    let release = MIDIMessage.controlChange(channel: 0, number: 101, value: 0)
    var held = BehaviorTrace()
    try held.input(touch)
    try held.step("set_parameter_80") { try $0.setParameter("a.Fader.1", value: 80) }
    traces["01-touch-defers-write"] = held
    try held.input(release)
    traces["02-release-reconciles"] = held
    var cross = BehaviorTrace()
    try cross.input(touch)
    try cross.step("set_parameter_80") { try $0.setParameter("a.Fader.1", value: 80) }
    try cross.input(.controlChange(channel: 0, number: 37, value: 20))
    try cross.input(release)
    traces["03-cross-layer-release"] = cross
    var layer = BehaviorTrace()
    try layer.input(.controlChange(channel: 0, number: 107, value: 127))
    do {
        try layer.session.state.validateLayerAssertion()
        Issue.record("Touched layer assertion was accepted")
    } catch CompactError.fadersTouched {
        try layer.step("request_layer_b") { _ in [] }
        layer.rows[layer.rows.count - 1]["result"] = ["accepted": false, "rejection_reason": "fadersTouched", "parameter_changes": [:], "action_count": 0]
        layer.rows[layer.rows.count - 1]["output"] = ["sent": [], "deferred": [], "suppressed": [["category": "mechanism_motion", "reason": "fadersTouched", "affected_controls": Array(1 ... 9)]]]
    }
    traces["04-touched-layer-refused"] = layer
    var changed = BehaviorTrace()
    try changed.input(.controlChange(channel: 0, number: 1, value: 20))
    try changed.step("select_layer_b") { try $0.selectLayer(.b) }
    traces["05-layer-invalidates-observation"] = changed
    var failure = BehaviorTrace()
    try failure.step("failed_motor_write", fails: true) { try $0.setFader(1, value: 80) }
    try failure.step("retry_same_desired_value") { try $0.setFader(1, value: 80) }
    traces["06-send-failure-cache"] = failure
    var ring = BehaviorTrace()
    try ring.step("set_ring_value") { try $0.setDisplayRing(1, value: 64) }
    // Exercise the actual style redraw primitive (session exposes no style API).
    var state = ring.session.state
    let styleOutput = try state.setRingStyle(1, style: .pan)
    try ring.step("style_redraw_and_same_value") { _ in styleOutput }
    let sameValue = try state.setRing(1, display: .position(CompactSession.ringSegment(for: 64)))
    #expect(styleOutput == [.controlChange(channel: 0, number: 10, value: 1), .controlChange(channel: 0, number: 26, value: 7)])
    #expect(sameValue.isEmpty) // Style command already reasserted the desired value.
    try ring.step("same_ring_value_after_redraw") { _ in sameValue }
    traces["07-ring-style-redraw"] = ring
    var linked = BehaviorTrace()
    var config = SurfaceConfiguration.neutral
    config.assignments.removeAll { $0.control == .fader(2) && $0.layer == .a }
    config.assignments.append(.init(control: .fader(2), layer: .a, action: .parameter("a.Fader.1")))
    _ = try linked.session.loadConfiguration(config)
    try linked.input(touch)
    try linked.step("write_shared_parameter") { try $0.setParameter("a.Fader.1", value: 80) }
    traces["08-shared-parameter-touch"] = linked
    for name in traces.keys.sorted() {
        let document: [String: Any] = try ["schema_version": 1, "scenario": name, "source": "mock", "steps": TraceDeclaration.rows(#require(traces[name]?.rows))]
        let data = try JSONSerialization.data(withJSONObject: document, options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]) + Data([10])
        let path = root.appendingPathComponent(name + ".json")
        if ProcessInfo.processInfo.environment["UPDATE_BEHAVIOR_TRACES"] == "1" {
            try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
            try data.write(to: path)
        }
        let stored = try Data(contentsOf: path)
        // Foundation implementations differ in spacing and numeric spelling (0.1 vs 0.10000000000000001).
        // Compare typed JSON content with exact Double equality, retaining booleans and array order.
        let decoder = JSONDecoder()
        let storedContent = try decoder.decode(TraceJSONContent.self, from: stored)
        let generatedContent = try decoder.decode(TraceJSONContent.self, from: data)
        #expect(storedContent == generatedContent, "Trace content differs: \(name)")
        #if canImport(Darwin)
            #expect(stored == data, "Trace bytes differ: \(name)")
        #endif
    }
}
